from leann.api import SearchResult
from leann.metadata_filter import MetadataFilterEngine
from collections import defaultdict


def apply_dynamic_filters(
    search_results: List[SearchResult],
    filter_specs: Dict[str, Dict[str, Any]],
    filter_logic: str = "AND"
) -> List[SearchResult]:
    """Apply dynamic metadata filters to search results with configurable logic.

    Args:
        search_results: List of SearchResult objects to filter
        filter_specs: Dictionary of filter specifications.
            Format: {"field_name": {"operator": value}}
            Example: {"category": {"==": "tech"}, "rating": {">=": 4.0}}
        filter_logic: "AND" (all filters must match) or "OR" (any filter matches)

    Returns:
        Filtered list of SearchResult objects
    """
    if not search_results or not filter_specs:
        return search_results

    # Validate filter logic
    if filter_logic not in ["AND", "OR"]:
        raise ValueError("filter_logic must be either 'AND' or 'OR'")

    # Create filter engine instance
    engine = MetadataFilterEngine()

    # Convert SearchResult objects to dictionaries for filtering
    result_dicts = []
    for result in search_results:
        # Convert SearchResult to dictionary format expected by the filter engine
        result_dict = {
            "metadata": result.metadata if hasattr(result, 'metadata') else {},
            "text": result.text if hasattr(result, 'text') else "",
            "score": result.score if hasattr(result, 'score') else 0.0,
            "id": result.id if hasattr(result, 'id') else None
        }
        # Add any additional attributes that might be present
        result_dict.update(result.__dict__)
        result_dicts.append((result, result_dict))

    # Apply filters based on the specified logic
    filtered_results = []

    for original_result, result_dict in result_dicts:
        if filter_logic == "AND":
            # All filters must match
            matches_all = True
            for field_name, operator_dict in filter_specs.items():
                if not matches_all:
                    break
                for operator, value in operator_dict.items():
                    # Create a single filter for this field and operator
                    single_filter = {field_name: {operator: value}}
                    if not engine._evaluate_filters(result_dict, single_filter):
                        matches_all = False
                        break
            if matches_all:
                filtered_results.append(original_result)

        else:  # OR logic
            # At least one filter must match
            matches_any = False
            for field_name, operator_dict in filter_specs.items():
                if matches_any:
                    break
                for operator, value in operator_dict.items():
                    # Create a single filter for this field and operator
                    single_filter = {field_name: {operator: value}}
                    if engine._evaluate_filters(result_dict, single_filter):
                        matches_any = True
                        break
            if matches_any:
                filtered_results.append(original_result)

    return filtered_results

