            field_coverage = {
                field: (count / total_passages) * 100 
                for field, count in field_presence_count.items()
            }

            # Find missing fields (fields not present in any passage)
            missing_fields = [
                field for field, count in field_presence_count.items() 
                if count == 0
            ]

            return {
                "coverage_percentage": round(coverage_percentage, 2),
                "field_coverage": {k: round(v, 2) for k, v in field_coverage.items()},
                "missing_fields": missing_fields
            }

    except Exception as e:
        # Fallback to metadata file analysis
        metadata_files = [
            index_path_obj / "metadata.json",
            index_path_obj / "index_metadata.json",
            index_path_obj / "passages" / "metadata.json"
        ]

        for metadata_file in metadata_files:
            if metadata_file.exists():
                try:
                    with open(metadata_file, 'r') as f:
                        metadata = json.load(f)

                    total_passages = metadata.get('total_passages', 0)
                    if total_passages == 0:
                        return {
                            "coverage_percentage": 0.0,
                            "field_coverage": {field: 0.0 for field in required_fields},
                            "missing_fields": required_fields.copy()
                        }

                    # Analyze passages metadata if available
                    passages_with_all_fields = 0
                    field_presence_count = {field: 0 for field in required_fields}

                    if 'passages' in metadata:
                        passages_metadata = metadata['passages']
                        for passage_meta in passages_metadata:
                            passage_has_all_fields = True

                            for field in required_fields:
                                if field in passage_meta.get('metadata', {}):
                                    field_presence_count[field] += 1
                                else:
                                    passage_has_all_fields = False

                            if passage_has_all_fields:
                                passages_with_all_fields += 1

                    coverage_percentage = (passages_with_all_fields / total_passages) * 100
                    field_coverage = {
                        field: (count / total_passages) * 100 
                        for field, count in field_presence_count.items()
                    }
                    missing_fields = [
                        field for field, count in field_presence_count.items() 
                        if count == 0
                    ]

                    return {
                        "coverage_percentage": round(coverage_percentage, 2),
                        "field_coverage": {k: round(v, 2) for k, v in field_coverage.items()},
                        "missing_fields": missing_fields
                    }

                except json.JSONDecodeError:
                    continue

        raise FileNotFoundError(f"Index metadata file not found for: {index_path}")
